{"chunk_id":"8cbc57","wall_time_seconds":0.000011623,"exit_code":0,"original_token_count":2351,"output":"@import "tailwindcss";

/*
 * TWYNE — The Editorial Room
 * ─────────────────────────────────────────────────────────────
 * Design language: a 1955 magazine bullpen filtered through
 * Wes Anderson's "The French Dispatch."  Newsprint paper,
 * editorial vermilion, periwinkle and sage departmental
 * accents, hot-press serif headlines, manuscript-grade body.
 * ─────────────────────────────────────────────────────────────
 */

@theme {
  /* ── Paper & Ink ─────────────────────────────────────── */
  --color-paper: #f4ecd8; /* aged newsprint cream */
  --color-paper-2: #ebe1c9; /* deeper paper, sidebars */
  --color-paper-3: #ddd0b1; /* paper rule */
  --color-paper-soft: #faf3df; /* highlight paper */
  --color-ink: #1f1b16; /* near-black brown */
  --color-ink-light: #4a3f33; /* secondary ink */
  --color-ink-muted: #8a7e6c; /* tertiary, set in old gravure */
  --color-editor-bg: #fbf6e7; /* manuscript page */
  --color-editor-line: #efe6cb; /* manuscript ledger line */

  /* ── Departmental Accents (color-coded sections) ─────── */
  --color-vermilion: #c1272d; /* Penguin Classics red, masthead */
  --color-vermilion-2: #9c1a1f; /* deeper vermilion */
  --color-periwinkle: #5c6bc0; /* periwinkle, departmental */
  --color-sage: #8a9a5b; /* cabinet sage */
  --color-mustard: #d4a017; /* color rule, badges */
  --color-blush: #e8a598; /* salmon, soft accents */
  --color-cobalt: #2c4a7c; /* deep ocean, callouts */

  /* legacy "brand" mapped to vermilion for compat */
  --color-brand: #c1272d;
  --color-brand-light: #d65157;
  --color-brand-dark: #9c1a1f;

  /* legacy "surface" mapped to paper for compat */
  --color-surface: #f4ecd8;
  --color-surface-2: #ebe1c9;
  --color-surface-3: #ddd0b1;

  /* ── Status colors (kept, but recalibrated for paper) ── */
  --color-accent-green: #5b7a3a;
  --color-accent-amber: #b8860b;
  --color-accent-red: #b3261e;
  --color-accent-blue: #2c4a7c;

  /* ── Cast colors (the persona portraits) ─────────────── */
  --color-persona-devil: #c1272d; /* vermilion */
  --color-persona-angel: #8a9a5b; /* sage */
  --color-persona-scholar: #5c6bc0; /* periwinkle */
  --color-persona-editor: #d4a017; /* mustard */
  --color-persona-reader: #2c4a7c; /* cobalt */

  /* ── Type stack ──────────────────────────────────────── */
  --font-display: "Fraunces", "Playfair Display", Georgia, serif;
  --font-serif: "Lora", "Crimson Pro", Georgia, "Times New Roman", serif;
  --font-sans: "DM Sans", "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", "Fira Code", monospace;
  --font-typewriter: "Special Elite", "Courier New", monospace;
}

/* ── Semantic z-scale ────────────────────────────────────── */
:root {
  --z-dropdown: 30;
  --z-sticky: 20;
  --z-overlay: 40;
  --z-modal: 50;
  --z-toast: 60;
}

/* ─────────────────────────────────────────────────────────────
 * Tokens referenced across the app that had no definition — they
 * were resolving to `unset`. Aliases, so they follow the theme.
 * ───────────────────────────────────────────────────────────── */
:root {
  --color-accent: var(--color-vermilion);
  --color-rule: var(--color-paper-3);
  --color-crimson: var(--color-vermilion-2);
}

/* Narration follows the prose without disturbing its Markdown structure. */
::highlight(twyne-speech-sentence) {
  background-color: color-mix(in srgb, var(--color-mustard) 20%, transparent);
}

::highlight(twyne-speech-word) {
  color: var(--color-ink);
  background-color: color-mix(
    in srgb,
    var(--color-vermilion) 26%,
    var(--color-paper)
  );
  text-decoration: underline;
  text-decoration-color: var(--color-vermilion);
  text-decoration-thickness: 2px;
  text-underline-offset: 0.16em;
}

[data-speech-active="playing"],
[data-speech-active="paused"] {
  cursor: text;
}

[data-speech-active="loading"] {
  cursor: progress;
}

[data-speech-active].is-speech-seeking {
  cursor: ew-resize;
  user-select: none;
}

/* ─────────────────────────────────────────────────────────────
 * Document colors — the text and highlight swatches in
 * `palette.ts`, which named these custom properties without any
 * of them ever being defined.
 *
 * Literal, and deliberately outside the theme blocks. These are
 * colors the writer applies to their prose; they get written into
 * the document as hex and have to render identically in an export
 * that has no stylesheet. A theme may re-ink the room, never the
 * manuscript.
 * ───────────────────────────────────────────────────────────── */
:root {
  --color-text-olive: #556134;
  --color-text-periwinkle: #454f9e;
  --color-text-amber: #7a5a07;
  --color-text-sienna: #964f40;
  --color-highlight-butter: #fbeaa8;
  --color-highlight-rose: #f8d3d4;
  --color-highlight-sky: #cfe0f2;
  --color-highlight-mint: #d5e6c4;
  --color-highlight-lilac: #dcdff4;
  --color-highlight-peach: #fadfd5;
}

/* ─────────────────────────────────────────────────────────────
 * Texture tokens
 *
 * The letterpress surfaces — paper grain, foxing, the `.folio`
 * emboss, `.ink-bleed`'s halo — used to hard-code `rgba(31,27,22,…)`
 * ink and `rgba(255,255,255,…)` highlights. Baked that way they
 * invert wrongly on any other ground: a white inset sheen on dark
 * paper reads as a scratch. Expressed against the palette instead,
 * every texture follows the active theme.
 * ───────────────────────────────────────────────────────────── */
:root {
  /* Paper tooth. Its own tokens so a preset can flatten it entirely. */
  --grain-1: color-mix(in srgb, var(--color-ink) 2.5%, transparent);
  --grain-2: color-mix(in srgb, var(--color-ink) 2%, transparent);
  --grain-3: color-mix(in srgb, var(--color-ink) 1.5%, transparent);
  /* Base colors the textures are mixed from, never used at full strength. */
  --emboss: #ffffff;
  --foxing-base: #7a5426;
  /*
   * The color shadows are cast in. On paper this is just the ink, but a
   * shadow always darkens — on a dark preset, mixing from ink would make
   * every drop shadow glow. Kept separate so presets can say so.
   */
  --shade: var(--color-ink);
}

/* ─────────────────────────────────────────────────────────────
 * Themes
 *
 * Each block redefines only the core palette; everything else is
 * expressed against it, so a preset switch is one attribute flip
 * on <html>. Writers may override the eight core tokens inline on
 * top of any preset — see `src/utils/theme.ts`.
 *
 * `system` is resolved to a concrete preset by the bootstrap
 * script before first paint, so no preset block is needed for it.
 * ───────────────────────────────────────────────────────────── */

/* Foolscap — cool grey-white, the yellow taken out. */
[data-theme="foolscap"] {
  --color-paper: #eef0f1;
  --color-paper-2: #e3e6e8;
  --color-paper-3: #c9ced2;
  --color-paper-soft: #f7f8f9;
  --color-ink: #1c2024;
  --color-ink-light: #3f464d;
  --color-ink-muted: #69727a;
  --color-editor-bg: #f9fafb;
  --color-editor-line: #e6e9eb;
  --color-vermilion: #9b4a52;
  --color-vermilion-2: #7d353d;
  --color-mustard: #9a7b2e;
  --color-surface: #eef0f1;
  --color-surface-2: #e3e6e8;
  --color-surface-3: #c9ced2;
  --color-brand: #9b4a52;
  --color-brand-light: #b76a72;
  --color-brand-dark: #7d353d;
  /* No newsprint browning on a cool ground — foxing goes grey. */
  --foxing-base: #6b727a;
}

/* Broadsheet — near-white, maximum contrast, minimum tint. */
[data-theme="broadsheet"] {
  --color-paper: #ffffff;
  --color-paper-2: #f4f4f4;
  --color-paper-3: #c4c4c4;
  --color-paper-soft: #fafafa;
  --color-ink: #111111;
  --color-ink-light: #333333;
  --color-ink-muted: #5c5c5c;
  --color-editor-bg: #ffffff;
  --color-editor-line: #ececec;
  --color-vermilion: #b3121a;
  --color-vermilion-2: #8c0d14;
  --color-surface: #ffffff;
  --color-surface-2: #f4f4f4;
  --color-surface-3: #c4c4c4;
  --color-brand: #b3121a;
  --color-brand-light: #d43c43;
  --color-brand-dark: #8c0d14;
"}

{"chunk_id":"807e22","wall_time_seconds":0.000009509,"exit_code":0,"original_token_count":1856,"output":"import {
  component$,
  useStore,
  useStylesScoped$,
  useVisibleTask$,
  $,
} from "@builder.io/qwik";
import { Link, type DocumentHead } from "@builder.io/qwik-city";
import type { DetectedCitation, Folio } from "../../types";
import { detectCitations } from "../../utils/citations";
import {
  type BibEntry,
  type CitationStyle,
  bibliographyForFolio,
  loadBibliographyForFolio,
  deleteBibEntry,
  formatCitation,
  buildBibEntryFromFormattedCitation,
  mergeBibEntry,
} from "../../utils/bibliography";
import {
  loadApparatusSettingsFromIdb,
  loadActiveFolioIdFromIdb,
  loadFoliosFromIdb,
  loadFolioContentFromIdb,
  saveApparatusSettingsToIdb,
} from "../../utils/idb";
import {
  formatResearchTime,
  retryBackgroundResearch,
  retryResearchTarget,
  snapshot as researchSnapshot,
  type ResearchActivityEntry,
  type ResearchProgressItem,
} from "../../utils/background-research";
import { targetKindLabel } from "../../utils/research-targets";
import type { McpResourceInfo } from "../../utils/mcp-client";
import {
  listMcpDocuments,
  mcpConvexClient,
  readMcpResource,
} from "../../utils/mcp-research";
import {
  hasConfiguredAiProvider,
  runClientCitationFormat,
  runClientSourceSummarize,
  runClientMissingSourceDetect,
} from "../../utils/ai-client";
import { loadAiSettingsFromIdb } from "../../utils/idb";
import type { AiSettings, SourceSummarizeResult } from "../../types";

interface ApparatusStore {
  bibliography: BibEntry[];
  citations: DetectedCitation[];
  style: CitationStyle;
  activeFolio: Folio | null;
  embedUrl: string | null;
  embedTitle: string;
  embedMarkdown: string | null;
  embedProvider: string | null;
  embedLoading: boolean;
  research: {
    status: "idle" | "running" | "saving" | "error";
    phase: string;
    passActive: boolean;
    lastQuery: string;
    lastQueryAt: number;
    savedThisSession: number;
    lastTickAt: number;
    provider?: string;
    error?: string;
    progress: ResearchProgressItem[];
    activity: ResearchActivityEntry[];
  };
  showResearchLog: boolean;
  /* ── AI-enhanced apparatus ─────────────────────────────────── */
  aiSettings: AiSettings | null;
  aiLoading: Record<string, boolean>;
  aiSummaries: Record<string, SourceSummarizeResult>;
  aiEnhanceCitations: boolean;
  flagMissingSources: boolean;
  /** Citation ids that have been added to the bibliography. */
  addedCitationIds: Record<string, boolean>;
  aiMissingSources: {
    claims: Array<{
      claim: string;
      reason: string;
      suggestedQuery: string;
    }>;
    provider: string;
  } | null;
  aiScanningMissing: boolean;
  /** Documents exposed by the writer's MCP servers, listed but not read. */
  mcpDocuments: Array<{ server: string; resource: McpResourceInfo }>;
}

const STYLE_OPTIONS: ReadonlyArray<{ value: CitationStyle; label: string }> = [
  { value: "mla", label: "MLA" },
  { value: "apa", label: "APA" },
  { value: "chicago", label: "Chicago" },
];

export default component$(() => {
  const store = useStore<ApparatusStore>({
    bibliography: [],
    citations: [],
    style: "mla",
    activeFolio: null,
    embedUrl: null,
    embedTitle: "",
    embedMarkdown: null,
    embedProvider: null,
    embedLoading: false,
    research: {
      status: "idle",
      phase: "idle",
      passActive: false,
      lastQuery: "",
      lastQueryAt: 0,
      savedThisSession: 0,
      lastTickAt: 0,
      progress: [],
      activity: [],
    },
    showResearchLog: false,
    aiSettings: null,
    aiLoading: {},
    aiSummaries: {},
    aiEnhanceCitations: false,
    flagMissingSources: false,
    addedCitationIds: {},
    aiMissingSources: null,
    aiScanningMissing: false,
    mcpDocuments: [],
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async () => {
    const apparatusSettings = await loadApparatusSettingsFromIdb();
    store.style = apparatusSettings.defaultCitationStyle;
    store.aiEnhanceCitations = apparatusSettings.aiEnhanceCitations;
    store.flagMissingSources = apparatusSettings.flagMissingSources;
    const folios = await loadFoliosFromIdb();
    const activeFolioId = await loadActiveFolioIdFromIdb();
    store.activeFolio =
      folios.find((folio) => folio.id === activeFolioId) ?? folios[0] ?? null;
    store.bibliography = await loadBibliographyForFolio(store.activeFolio?.id);
    if (store.activeFolio) {
      const html = await loadFolioContentFromIdb(store.activeFolio.id);
      const text = html.replace(/<[^>]+>/g, " ");
      store.citations = detectCitations(text);
    }
    store.aiSettings = await loadAiSettingsFromIdb();

    // Knowledge bases are listed, not read: listing is one round trip per
    // server, while reading every document on page load would not be.
    if (apparatusSettings.mcpServers.some((s) => s.enabled && s.useResources)) {
      try {
        store.mcpDocuments = await listMcpDocuments(
          apparatusSettings,
          mcpConvexClient(),
        );
      } catch {
        // An unreachable server is reported in Settings, not here.
      }
    }

    if (
      store.aiEnhanceCitations &&
      hasConfiguredAiProvider(store.aiSettings) &&
      store.aiSettings &&
      store.activeFolio
    ) {
      for (const citation of store.citations) {
        const entryId = `ai-fmt-${store.activeFolio.id}-${citation.id}`.replace(
          /[^a-zA-Z0-9_-]/g,
          "-",
        );
        if (store.bibliography.some((entry) => entry.id === entryId)) continue;
        const result = await runClientCitationFormat(
          {
            rawText: citation.text,
            style: store.style,
            context: store.activeFolio.name,
          },
          store.aiSettings,
        );
        if (!result) continue;
        const all = await mergeBibEntry(
          buildBibEntryFromFormattedCitation(
            citation,
            result,
            store.activeFolio.id,
          ),
        );
        store.bibliography = bibliographyForFolio(all, store.activeFolio?.id);
      }
    }
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(() => {
    const pull = () => {
      const s = researchSnapshot();
      store.research = {
        status: s.status as ApparatusStore["research"]["status"],
        phase: s.phase,
        passActive: s.passActive,
        lastQuery: s.lastQuery,
        lastQueryAt: s.lastQueryAt,
        savedThisSession: s.savedThisSession,
        lastTickAt: s.lastTickAt,
        provider: s.provider,
        error: s.error,
        progress: s.progress,
        activity: s.activity,
      };
    };
    const onSources = () => {
      void loadBibliographyForFolio(store.activeFolio?.id).then((entries) => {
        store.bibliography = entries;
      });
    };
    pull();
    window.addEventListener("twyne:background-research", pull);
    window.addEventListener("twyne:background-sources", onSources);
    return () => {
      window.removeEventListener("twyne:background-research", pull);
      window.removeEventListener("twyne:background-sources", onSources);
    };
  });

  useStylesScoped$(`
    .style-toggle {
      display: inline-flex; border: 1px solid var(--color-paper-3);
      border-radius: 2px; overflow: hidden;
    }
    .style-toggle button {
      padding: 0.2rem 0.6rem;
      font-family: var(--font-typewriter);
"}

